import json
from pydantic import BaseModel, ValidationError, Field

class Ticket(BaseModel):
    category: str
    priority: int = Field(ge=1, le=5)  # range enforced by YOUR validator

def get_ticket(client, prompt):
    for attempt in range(2):
        r = client.messages.create(model="claude-opus-5-5", max_tokens=1024,
            messages=[{"role": "user", "content": prompt}],
            output_config={"format": {"type": "json_schema", "schema": Ticket.model_json_schema()}})
        if r.stop_reason in ("max_tokens", "refusal"):
            raise RuntimeError(r.stop_reason)
        text = next(b.text for b in r.content if b.type == "text")
        try:
            return Ticket.model_validate(json.loads(text))
        except (json.JSONDecodeError, ValidationError):
            continue
